6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3630,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 13.5\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T650,"])self.__next_f.push([1,"The Supreme Personality of Godhead, Kṛṣṇa, is the highest authority in explaining this knowledge. Still, as a matter of course, learned scholars and standard authorities always give evidence from previous authorities. Kṛṣṇa is explaining this most controversial point regarding the duality and nonduality of the soul and the Supersoul by referring to a scripture, the Vedānta, which is accepted as authority. First He says, “This is according to different sages.” As far as the sages are concerned, besides Himself, Vyāsadeva (the author of the Vedānta-sūtra) is a great sage, and in the Vedānta-sūtra duality is perfectly explained. And Vyāsadeva’s father, Parāśara, is also a great sage, and he writes in his books of religiosity, aham tvaṁ ca tathānye.… “we – you, I and the various other living entities – are all transcendental, although in material bodies. Now we are fallen into the ways of the three modes of material nature according to our different karma. As such, some are on higher levels, and some are in the lower nature. The higher and lower natures exist due to ignorance and are being manifested in an infinite number of living entities. But the Supersoul, which is infallible, is uncontaminated by the three qualities of nature and is transcendental.” Similarly, in the original Vedas, a distinction between the soul, the Supersoul and the body is made, especially in the Kaṭha Upaniṣad. There are many great sages who have explained this, and Parāśara is considered principal among them."])self.__next_f.push([1,"26:T871,"])self.__next_f.push([1,"As stated before, kṣetra is the field of activities, and there are two kinds of kṣetra-jña: the individual living entity and the supreme living entity. As stated in the Taittirīya Upaniṣad (2.5), brahma pucchaṁ pratiṣṭhā. There is a manifestation of the Supreme Lord’s energy known as anna-maya, dependence upon food for existence. This is a materialistic realization of the Supreme. Then, in prāṇa-maya, after realizing the Supreme Absolute Truth in food, one can realize the Absolute Truth in the living symptoms or life forms. In jñāna-maya, realization extends beyond the living symptoms to the point of thinking, feeling and willing. Then there is Brahman realization, called vijñāna-maya, in which the living entity’s mind and life symptoms are distinguished from the living entity himself. The next and supreme stage is ānanda-maya, realization of the all-blissful nature. Thus there are five stages of Brahman realization, which are called brahma puccham. Out of these, the first three – anna-maya, prāṇa-maya and jñāna-maya – involve the fields of activities of the living entities. Transcendental to all these fields of activities is the Supreme Lord, who is called ānanda-maya. The Vedānta-sūtra also describes the Supreme by saying, ānanda-mayo ’bhyāsāt: the Supreme Personality of Godhead is by nature full of joy. To enjoy His transcendental bliss, He expands into vijñāna-maya, prāṇa-maya, jñāna-maya and anna-maya. In the field of activities the living entity is considered to be the enjoyer, and different from him is the ānanda-maya. That means that if the living entity decides to enjoy in dovetailing himself with the ānanda-maya, then he becomes perfect. This is the real picture of the Supreme Lord as the supreme knower of the field, the living entity as the subordinate knower, and the nature of the field of activities. One has to search for this truth in the Vedānta-sūtra, or Brahma-sūtra."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3630,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"5\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 5\",\"advanced_view_url_path\":\"/en/library/bg/13/advanced-view/#bb3199\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/13/5/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/13/5/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/13/5/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/13/5/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/13/5/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"en