nks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3649,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 13.8-12\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T823,"])self.__next_f.push([1,"amānitvam – humility; adambhitvam – pridelessness; ahiṁsā – nonviolence; kṣāntiḥ – tolerance; ārjavam – simplicity; ācārya-upāsanam – approaching a bona fide spiritual master; śaucam – cleanliness; sthairyam – steadfastness; ātma-vinigrahaḥ – self-control; indriya-artheṣu – in the matter of the senses; vairāgyam – renunciation; anahaṅkāraḥ – being without false egoism; eva – certainly; ca – also; janma – of birth; mṛtyu – death; jarā – old age; vyādhi – and disease; duḥkha – of the distress; doṣa – the fault; anudarśanam – observing; asaktiḥ – being without attachment; anabhiṣvaṅgaḥ – being without association; putra – for son; dāra – wife; gṛha-ādiṣu – home, etc.; nityam – constant; ca – also; sama-cittatvam – equilibrium; iṣṭa – the desirable; aniṣṭa – and undesirable; upapattiṣu – having obtained; mayi – unto Me; ca – also; ananya-yogena – by unalloyed devotional service; bhaktiḥ – devotion; avyabhicāriṇī – without any break; vivikta – to solitary; deśa – places; sevitvam – aspiring; aratiḥ – being without attachment; jana-saṁsadi – to people in general; adhyātma – pertaining to the self; jñāna – in knowledge; nityatvam – constancy; tattva-jñāna – of knowledge of the truth; artha – for the object; darśanam – philosophy; etat – all this; jñānam – knowledge; iti – thus; proktam – declared; ajñānam – ignorance; yat – that which; ataḥ – from this; anyathā – other."])self.__next_f.push([1,"26:T73a,"])self.__next_f.push([1,"This process of knowledge is sometimes misunderstood by less intelligent men as being the interaction of the field of activity. But actually this is the real process of knowledge. If one accepts this process, then the possibility of approaching the Absolute Truth exists. This is not the interaction of the twenty-four elements, as described before. This is actually the means to get out of the entanglement of those elements. The embodied soul is entrapped by the body, which is a casing made of the twenty-four elements, and the process of knowledge as described here is the means to get out of it. Of all the descriptions of the process of knowledge, the most important point is described in the first line of the eleventh verse. Mayi cānanya-yogena bhaktir avyabhicāriṇī: the process of knowledge terminates in unalloyed devotional service to the Lord. So if one does not approach, or is not able to approach, the transcendental service of the Lord, then the other nineteen items are of no particular value. But if one takes to devotional service in full Kṛṣṇa consciousness, the other nineteen items automatically develop within him. As stated in Śrīmad-Bhāgavatam (5.18.12), yasyāsti bhaktir bhagavaty akiñcanā sarvair guṇais tatra samāsate surāḥ. All the good qualities of knowledge develop in one who has attained the stage of devotional service. The principle of accepting a spiritual master, as mentioned in the eighth verse, is essential. Even for one who takes to devotional service, it is most important. Transcendental life begins when one accepts a bona fide spiritual master. The Supreme Personality of Godhead, Śrī Kṛṣṇa, clearly states here that this process of knowledge is the actual path. Anything speculated beyond this is nonsense."])self.__next_f.push([1,"27:T6b8,"])self.__next_f.push([1,"Steadiness means that one should be very determined to make progress in spiritual life. Without such determination, one cannot make tangible progress. And self-control means that one should not accept anything which is detrimental to the path of spiritual progress. One should become accustomed to this and reject anything which is against the path of spiritual progress. This is real renunciation. The senses are so strong that they are always anxious to have sense gratification. One should not cater to these demands, which are not necessary. The senses should only be gratified to keep the body fit so that one can discharge his duty in advancing in spiritual life. The most important and uncontrollable sense is the tongue. If one can control the tongue, then there is every possibility of controlling the other senses. The function of the tongue is to taste and to vibrate. Therefore, by systematic regulation, the tongue should always be engaged in tasting the remnants of foodstuffs offered to Kṛṣṇa and chanting Hare Kṛṣṇa. As far as the eyes are concerned, they should not be allowed to see anything but the beautiful form of Kṛṣṇa. That will control the eyes. Similarly, the ears should be engaged in hearing about Kṛṣṇa and the nose in smelling the flowers offered to Kṛṣṇa. This is the process of devotional service, and it is understood here that Bhagavad-gītā is simply expounding the science of devotional service. Devotional service is the main and sole objective. Unintelligent commentators on the Bhagavad-gītā try to divert the mind of the reader to other subjects, but there is no other subject in Bhagavad-gītā than devotional service."])self.__next_f.push([1,"28:T418,One should try to understand the distress of accepting birth, death, old age and disease. There are descriptions in various Vedic literatures of birth. In the Śrīmad-Bhāgavatam the world of the unborn, the child’s stay in the womb of the mother, its suffering, etc., are all very graphically described. It should be thoroughly understood that birth is distressful. Because we forget how much distress we have suffered within the womb of the mother, we do not make any solution to the repetition of birth and death. Similarly at the time of death there are all kinds of sufferings, and they are also mentioned in the authoritative scriptures. These should be discussed. And as far as disease and old age are concerned, everyone gets practical experience. No one wants to be diseased, and no one wants to become old, but there is no avoiding these. Unless we have a pessimistic view of this material life, considering the distresses of birth, death, old age and disease, there is no impetus for our making advancement in spiritual life.29:T71d,"])self.__next_f.push([1,"As for detachment from children, wife and home, it is not meant that one should have no feeling for these. They are natural objects of affection. But when they are not favorable to spiritual progress, then one should not be attached to them. The best process for making the home pleasant is Kṛṣṇa consciousness. If one is in full Kṛṣṇa consciousness, he can make his home very happy, because this process of Kṛṣṇa consciousness is very easy. One need only chant Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare, accept the remnants of foodstuffs offered to Kṛṣṇa, have some discussion on books like Bhagavad-gītā and Śrīmad-Bhāgavatam, and engage oneself in Deity worship. These four things will make one happy. One should train the members of his family in this way. The family members can sit down morning and evening and chant together Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare. If one can mold his family life in this way to develop Kṛṣṇa consciousness, following these four principles, then there is no need to change from family life to renounced life. But if it is not congenial, not favorable for spiritual advancement, then family life should be abandoned. One must sacrifice everything to realize or serve Kṛṣṇa, just as Arjuna did. Arjuna did not want to kill his family members, but when he understood that these family members were impediments to his Kṛṣṇa realization, he accepted the instruction of Kṛṣṇa and fought and killed them. In all cases, one should be detached from the happiness and distress of family life, because in this world one can never be fully happy or fully miserable."])self.__next_f.push([1,"2a:T468,Beginning from practicing humility up to the point of realization of the Supreme Truth, the Absolute Personality of Godhead, this process is just like a staircase beginning from the ground floor and going up to the top floor. Now on this staircase there are so many people who have reached the first floor, the second or the third floor, etc., but unless one reaches the top floor, which is the understanding of Kṛṣṇa, he is at a lower stage of knowledge. If anyone wants to compete with God and at the same time make advancement in spiritual knowledge, he will be frustrated. It is clearly stated that without humility, understanding is not truly possible. To think oneself God is most puffed up. Although the living entity is always being kicked by the stringent laws of material nature, he still thinks, “I am God” because of ignorance. The beginning of knowledge, therefore, is amānitva, humility. One should be humble and know that he is subordinate to the Supreme Lord. Due to rebellion against the Supreme Lord, one becomes subordinate to material nature. One must know and be convinced of this truth."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3649,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"8-12\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 8-12\",\"advanced_view_url_path\":\"/en/library/bg/13/advanced-view/#bb3216\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/13/8-12/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/13/8-12/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/13/8-12/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/13/8-12/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/13/8-12/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/13/8-12/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/13/8-12/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/13/8-12/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/13/8-12/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu/library/bg/13/8-12/\"},{\"display_name\":\"日本語 (Japanese)\",\"language_code\":\"ja\",\"enabled\":true,\"url_path\":\"/ja/library/bg/13/8-12/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/13/8-12/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/13/8-12/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/13/8-12/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/13/8-12/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/13/8-12/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/13/8-12/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/13/8-12/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/13/8-12/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/13/8-12/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/13/\",\"title\":\"Chapter Thirteen: Nature, the Enjoyer and Consciousness\"}],\"url_path\":\"/en/library/bg/13/8-12/\",\"bb\":3216,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/13/6-7/\",\"title\":\"TEXTS 6-7\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/13/13/\",\"title\":\"TEXT 13\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3650,\"bb\":568355,\"url_path\":\"/en/library/bg/13/8-12/devanagari/\",\"body_final\":\"अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम् ।
आचार्योपासनं शौचं स्थैर्यमात्मविनिग्रह: ॥ ८ ॥
इन्द्रियार्थेषु वैराग्यमनहङ्कार एव च ।
जन्ममृत्युजराव्याधिदु:खदोषानुदर्शनम् ॥ ९ ॥
असक्तिरनभिष्वङ्ग: पुत्रदारगृहादिषु ।
नित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु ॥ १० ॥
मयि चानन्ययोगेन भक्तिरव्यभिचारिणी ।
विविक्तदेशसेवित्वमरतिर्जनसंसदि ॥ ११ ॥
अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम् ।
एतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोऽन्यथा ॥ १२ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3651,\"bb\":3217,\"url_path\":\"/en/library/bg/13/8-12/b3217/\",\"body_value\":\"amānitvam adambhitvam
ahiṁsā kṣāntir ārjavam
ācāryopāsanaṁ śaucaṁ
sthairyam ātma-vinigrahaḥ\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3652,\"bb\":3218,\"url_path\":\"/en/library/bg/13/8-12/b3218/\",\"body_value\":\"indriyārtheṣu vairāgyam
anahaṅkāra eva ca
janma-mṛtyu-jarā-vyādhi-
duḥkha-doṣānudarśanam\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3653,\"bb\":3219,\"url_path\":\"/en/library/bg/13/8-12/b3219/\",\"body_value\":\"asaktir anabhiṣvaṅgaḥ
putra-dāra-gṛhādiṣu
nityaṁ ca sama-cittatvam
iṣṭāniṣṭopapattiṣu\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3654,\"bb\":3220,\"url_path\":\"/en/library/bg/13/8-12/b3220/\",\"body_value\":\"mayi cānanya-yogena
bhaktir avyabhicāriṇī
vivikta-deśa-sevitvam
aratir jana-saṁsadi\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3655,\"bb\":3221,\"url_path\":\"/en/library/bg/13/8-12/b3221/\",\"body_value\":\"adhyātma-jñāna-nityatvaṁ
tattva-jñānārtha-darśanam
etaj jñānam iti proktam
ajñānaṁ yad ato ’nyathā\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3656,\"bb\":3222,\"url_path\":\"/en/library/bg/13/8-12/b3222/\",\"shadow_value\":\"$25\",\"word_for_word_value\":[{\"word\":\"amānitvam\",\"translation\":\"humility\"},{\"word\":\"adambhitvam\",\"translation\":\"pridelessness\"},{\"word\":\"ahiṁsā\",\"translation\":\"nonviolence\"},{\"word\":\"kṣāntiḥ\",\"translation\":\"tolerance\"},{\"word\":\"ārjavam\",\"translation\":\"simplicity\"},{\"word\":\"ācārya-upāsanam\",\"translation\":\"approaching a bona fide spiritual master\"},{\"word\":\"śaucam\",\"translation\":\"cleanliness\"},{\"word\":\"sthairyam\",\"translation\":\"steadfastness\"},{\"word\":\"ātma-vinigrahaḥ\",\"translation\":\"self-control\"},{\"word\":\"indriya-artheṣu\",\"translation\":\"in the matter of the senses\"},{\"word\":\"vairāgyam\",\"translation\":\"renunciation\"},{\"word\":\"anahaṅkāraḥ\",\"translation\":\"being without false egoism\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"janma\",\"translation\":\"of birth\"},{\"word\":\"mṛtyu\",\"translation\":\"death\"},{\"word\":\"jarā\",\"translation\":\"old age\"},{\"word\":\"vyādhi\",\"translation\":\"and disease\"},{\"word\":\"duḥkha\",\"translation\":\"of the distress\"},{\"word\":\"doṣa\",\"translation\":\"the fault\"},{\"word\":\"anudarśanam\",\"translation\":\"observing\"},{\"word\":\"asaktiḥ\",\"translation\":\"being without attachment\"},{\"word\":\"anabhiṣvaṅgaḥ\",\"translation\":\"being without association\"},{\"word\":\"putra\",\"translation\":\"for son\"},{\"word\":\"dāra\",\"translation\":\"wife\"},{\"word\":\"gṛha-ādiṣu\",\"translation\":\"home, etc.\"},{\"word\":\"nityam\",\"translation\":\"constant\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"sama-cittatvam\",\"translation\":\"equilibrium\"},{\"word\":\"iṣṭa\",\"translation\":\"the desirable\"},{\"word\":\"aniṣṭa\",\"translation\":\"and undesirable\"},{\"word\":\"upapattiṣu\",\"translation\":\"having obtained\"},{\"word\":\"mayi\",\"translation\":\"unto Me\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"ananya-yogena\",\"translation\":\"by unalloyed devotional service\"},{\"word\":\"bhaktiḥ\",\"translation\":\"devotion\"},{\"word\":\"avyabhicāriṇī\",\"translation\":\"without any break\"},{\"word\":\"vivikta\",\"translation\":\"to solitary\"},{\"word\":\"deśa\",\"translation\":\"places\"},{\"word\":\"sevitvam\",\"translation\":\"aspiring\"},{\"word\":\"aratiḥ\",\"translation\":\"being without attachment\"},{\"word\":\"jana-saṁsadi\",\"translation\":\"to people in general\"},{\"word\":\"adhyātma\",\"translation\":\"pertaining to the self\"},{\"word\":\"jñāna\",\"translation\":\"in knowledge\"},{\"word\":\"nityatvam\",\"translation\":\"constancy\"},{\"word\":\"tattva-jñāna\",\"translation\":\"of knowledge of the truth\"},{\"word\":\"artha\",\"translation\":\"for the object\"},{\"word\":\"darśanam\",\"translation\":\"philosophy\"},{\"word\":\"etat\",\"translation\":\"all this\"},{\"word\":\"jñānam\",\"translation\":\"knowledge\"},{\"word\":\"iti\",\"translation\":\"thus\"},{\"word\":\"proktam\",\"translation\":\"declared\"},{\"word\":\"ajñānam\",\"translation\":\"ignorance\"},{\"word\":\"yat\",\"translation\":\"that which\"},{\"word\":\"ataḥ\",\"translation\":\"from this\"},{\"word\":\"anyathā\",\"translation\":\"other\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3657,\"bb\":3223,\"url_path\":\"/en/library/bg/13/8-12/b3223/\",\"body_value\":\"Humility; pridelessness; nonviolence; tolerance; simplicity; approaching a bona fide spiritual master; cleanliness; steadiness; self-control; renunciation of the objects of sense gratification; absence of false ego; the perception of the evil of birth, death, old age and disease; detachment; freedom from entanglement with children, wife, home and the rest; even-mindedness amid pleasant and unpleasant events; constant and unalloyed devotion to Me; aspiring to live in a solitary place; detachment from the general mass of people; accepting the importance of self-realization; and philosophical search for the Absolute Truth – all these I declare to be knowledge, and besides this whatever there may be is ignorance.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3658,\"bb\":3224,\"url_path\":\"/en/library/bg/13/8-12/b3224/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3659,\"bb\":3225,\"url_path\":\"/en/library/bg/13/8-12/b3225/\",\"body_value\":\"As for the knowledge outlined here, the items may be analyzed as follows. Humility means that one should not be anxious to have the satisfaction of being honored by others. The material conception of life makes us very eager to receive honor from others, but from the point of view of a man in perfect knowledge – who knows that he is not this body – anything, honor or dishonor, pertaining to this body is useless. One should not be hankering after this material deception. People are very anxious to be famous for their religion, and consequently sometimes it is found that without understanding the principles of religion one enters into some group which is not actually following religious principles and then wants to advertise himself as a religious mentor. As for actual advancement in spiritual science, one should have a test to see how far he is progressing. He can judge by these items.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3660,\"bb\":3226,\"url_path\":\"/en/library/bg/13/8-12/b3226/\",\"body_value\":\"Nonviolence is generally taken to mean not killing or destroying the body, but actually nonviolence means not to put others into distress. People in general are trapped by ignorance in the material concept of life, and they perpetually suffer material pains. So unless one elevates people to spiritual knowledge, one is practicing violence. One should try his best to distribute real knowledge to the people, so that they may become enlightened and leave this material entanglement. That is nonviolence.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3661,\"bb\":3227,\"url_path\":\"/en/library/bg/13/8-12/b3227/\",\"body_value\":\"Tolerance means that one should be practiced to bear insult and dishonor from others. If one is engaged in the advancement of spiritual knowledge, there will be so many insults and much dishonor from others. This is expected because material nature is so constituted. Even a boy like Prahlāda, who, only five years old, was engaged in the cultivation of spiritual knowledge, was endangered when his father became antagonistic to his devotion. The father tried to kill him in so many ways, but Prahlāda tolerated him. So there may be many impediments to making advancement in spiritual knowledge, but we should be tolerant and continue our progress with determination.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3662,\"bb\":3228,\"url_path\":\"/en/library/bg/13/8-12/b3228/\",\"body_value\":\"Simplicity means that without diplomacy one should be so straightforward that he can disclose the real truth even to an enemy. As for acceptance of the spiritual master, that is essential, because without the instruction of a bona fide spiritual master one cannot progress in the spiritual science. One should approach the spiritual master with all humility and offer him all services so that he will be pleased to bestow his blessings upon the disciple. Because a bona fide spiritual master is a representative of Kṛṣṇa, if he bestows any blessings upon his disciple, that will make the disciple immediately advanced without the disciple’s following the regulative principles. Or, the regulative principles will be easier for one who has served the spiritual master without reservation.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3663,\"bb\":3229,\"url_path\":\"/en/library/bg/13/8-12/b3229/\",\"body_value\":\"Cleanliness is essential for making advancement in spiritual life. There are two kinds of cleanliness: external and internal. External cleanliness means taking a bath, but for internal cleanliness one has to think of Kṛṣṇa always and chant Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare. This process cleans the accumulated dust of past karma from the mind.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3664,\"bb\":3230,\"url_path\":\"/en/library/bg/13/8-12/b3230/\",\"body_value\":\"$27\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3665,\"bb\":3231,\"url_path\":\"/en/library/bg/13/8-12/b3231/\",\"body_value\":\"False ego means accepting this body as oneself. When one understands that he is not his body and is spirit soul, he comes to his real ego. Ego is there. False ego is condemned, but not real ego. In the Vedic literature (Bṛhad-āraṇyaka Upaniṣad 1.4.10) it is said, ahaṁ brahmāsmi: I am Brahman, I am spirit. This “I am,” the sense of self, also exists in the liberated stage of self-realization. This sense of “I am” is ego, but when the sense of “I am” is applied to this false body it is false ego. When the sense of self is applied to reality, that is real ego. There are some philosophers who say we should give up our ego, but we cannot give up our ego, because ego means identity. We ought, of course, to give up the false identification with the body.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3666,\"bb\":3232,\"url_path\":\"/en/library/bg/13/8-12/b3232/\",\"body_value\":\"$28\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3667,\"bb\":3233,\"url_path\":\"/en/library/bg/13/8-12/b3233/\",\"body_value\":\"$29\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3668,\"bb\":3234,\"url_path\":\"/en/library/bg/13/8-12/b3234/\",\"body_value\":\"Happiness and distress are concomitant factors of material life. One should learn to tolerate, as advised in Bhagavad-gītā. One can never restrict the coming and going of happiness and distress, so one should be detached from the materialistic way of life and be automatically equipoised in both cases. Generally, when we get something desirable we are very happy, and when we get something undesirable we are distressed. But if we are actually in the spiritual position these things will not agitate us. To reach that stage, we have to practice unbreakable devotional service. Devotional service to Kṛṣṇa without deviation means engaging oneself in the nine processes of devotional service – chanting, hearing, worshiping, offering respect, etc. – as described in the last verse of the Ninth Chapter. That process should be followed.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3669,\"bb\":3235,\"url_path\":\"/en/library/bg/13/8-12/b3235/\",\"body_value\":\"Naturally, when one is adapted to the spiritual way of life, he will not want to mix with materialistic men. That would go against his grain. One may test himself by seeing how far he is inclined to live in a solitary place, without unwanted association. Naturally a devotee has no taste for unnecessary sporting or cinema-going or enjoying some social function, because he understands that these are simply a waste of time. There are many research scholars and philosophers who study sex life or some other subject, but according to Bhagavad-gītā such research work and philosophical speculation have no value. That is more or less nonsensical. According to Bhagavad-gītā, one should make research, by philosophical discretion, into the nature of the soul. One should make research to understand the self. That is recommended here.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3670,\"bb\":3236,\"url_path\":\"/en/library/bg/13/8-12/b3236/\",\"body_value\":\"As far as self-realization is concerned, it is clearly stated here that bhakti-yoga is especially practical. As soon as there is a question of devotion, one must consider the relationship between the Supersoul and the individual soul. The individual soul and the Supersoul cannot be one, at least not in the bhakti conception, the devotional conception of life. This service of the individual soul to the Supreme Soul is eternal, nityam, as it is clearly stated. So bhakti, or devotional service, is eternal. One should be established in that philosophical conviction.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3671,\"bb\":3237,\"url_path\":\"/en/library/bg/13/8-12/b3237/\",\"body_value\":\"In the Śrīmad-Bhāgavatam (1.2.11) this is explained. Vadanti tat tattva-vidas tattvaṁ yaj jñānam advayam. “Those who are actually knowers of the Absolute Truth know that the Self is realized in three different phases, as Brahman, Paramātmā and Bhagavān.” Bhagavān is the last word in the realization of the Absolute Truth; therefore one should reach up to that platform of understanding the Supreme Personality of Godhead and thus engage in the devotional service of the Lord. That is the perfection of knowledge.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3672,\"bb\":3238,\"url_path\":\"/en/library/bg/13/8-12/b3238/\",\"body_value\":\"$2a\"}]}],\"short_title\":\"Bg. 13.8-12\",\"medium_title\":\"Bhagavad-gītā As It Is 13.8-12\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L2b\",\"$L2c\",\"$L2d\"]}]\n"])self.__next_f.push([1,"2f:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt