\"$L20\",\"wfwundefined-0-nityatvam\",{\"href\":\"/en/search/synonyms/?original=nityatvam\",\"children\":[\"$\",\"em\",null,{\"children\":\"nityatvam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"constancy\"}}],\"; \"]}]\n58:[\"$\",\"span\",\"wfwundefined-45\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tattva\",{\"href\":\"/en/search/synonyms/?original=tattva\",\"children\":[\"$\",\"em\",null,{\"children\":\"tattva\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-jñāna\",{\"href\":\"/en/search/synonyms/?original=jñāna\",\"children\":[\"$\",\"em\",null,{\"children\":\"jñāna\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of knowledge of the truth\"}}],\"; \"]}]\n59:[\"$\",\"span\",\"wfwundefined-46\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-artha\",{\"href\":\"/en/search/synonyms/?original=artha\",\"children\":[\"$\",\"em\",null,{\"children\":\"artha\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"for the object\"}}],\"; \"]}]\n5a:[\"$\",\"span\",\"wfwundefined-47\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-darśanam\",{\"href\":\"/en/search/synonyms/?original=darśanam\",\"children\":[\"$\",\"em\",null,{\"children\":\"darśanam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"philosophy\"}}],\"; \"]}]\n5b:[\"$\",\"span\",\"wfwundefined-48\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-etat\",{\"href\":\"/en/search/synonyms/?original=etat\",\"children\":[\"$\",\"em\",null,{\"children\":\"etat\"}]}]],\" — \",[\"$\","])self.__next_f.push([1,"\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"all this\"}}],\"; \"]}]\n5c:[\"$\",\"span\",\"wfwundefined-49\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-jñānam\",{\"href\":\"/en/search/synonyms/?original=jñānam\",\"children\":[\"$\",\"em\",null,{\"children\":\"jñānam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"knowledge\"}}],\"; \"]}]\n5d:[\"$\",\"span\",\"wfwundefined-50\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-iti\",{\"href\":\"/en/search/synonyms/?original=iti\",\"children\":[\"$\",\"em\",null,{\"children\":\"iti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"thus\"}}],\"; \"]}]\n5e:[\"$\",\"span\",\"wfwundefined-51\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-proktam\",{\"href\":\"/en/search/synonyms/?original=proktam\",\"children\":[\"$\",\"em\",null,{\"children\":\"proktam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"declared\"}}],\"; \"]}]\n5f:[\"$\",\"span\",\"wfwundefined-52\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ajñānam\",{\"href\":\"/en/search/synonyms/?original=ajñānam\",\"children\":[\"$\",\"em\",null,{\"children\":\"ajñānam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"ignorance\"}}],\"; \"]}]\n60:[\"$\",\"span\",\"wfwundefined-53\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yat\",{\"href\":\"/en/search/synonyms/?original=yat\",\"children\":[\"$\",\"em\",null,{\"children\":\"yat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"that which\"}}],\"; \"]}]\n61:[\"$\",\"span\",\"wfwundefined-54\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ataḥ\",{\"href\":\"/en/search/synonyms/?original=ataḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"ataḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"from this\"}}],\"; \"]}]\n62:[\"$\",\"span\",\"wfwundefined-55\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-anyathā\",{\"href\":\"/en/search/synonyms/?original=anyathā\",\"children\":[\"$\",\"em\",null,{\"children\":\"anyathā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"other\"}}],\".\"]}]\n63:[\"$\",\"$L2f\",\"child-3661\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Tolerance means that one should be practiced to bear insult and dishonor from others. If one is engaged in the advancement of spiritual knowledge, there will be so many insults and much dishonor from others. This is expected because material nature is so constituted. Even a boy like Prahlāda, who, only five years old, was engaged in the cultivation of spiritual knowledge, was endangered when his father became antagonistic to his devotion. The father tried to kill him in so many ways, but Prahlāda tolerated him. So there may be many impediments to making advancement in spiritual knowledge, but we should be tolerant and continue our progress with determination.\"}}]}]\n64:[\"$\",\"$L2f\",\"child-3662\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:4\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Simplicity means that without diplomacy one should be so straightforward that he can disclose the real truth even to an enemy. As for acceptance of the spiritual master, that is essential, because without the instruction of a bona fide spiritual master one cannot progress in the spiritual science. One should approach the spiritual master with all humility and offer him all services so that he will be pleased to bestow his blessings upon the disciple. Because a bona fide spiritual master is a representative of Kṛṣṇa, if he bestows any blessings upon his disciple, that will make the disciple immediately advanced without the disciple’s following the regulative p"])self.__next_f.push([1,"rinciples. Or, the regulative principles will be easier for one who has served the spiritual master without reservation.\"}}]}]\n65:[\"$\",\"$L2f\",\"child-3663\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:5\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Cleanliness is essential for making advancement in spiritual life. There are two kinds of cleanliness: external and internal. External cleanliness means taking a bath, but for internal cleanliness one has to think of Kṛṣṇa always and chant Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare. This process cleans the accumulated dust of past karma from the mind.\"}}]}]\n70:T6b8,"])self.__next_f.push([1,"Steadiness means that one should be very determined to make progress in spiritual life. Without such determination, one cannot make tangible progress. And self-control means that one should not accept anything which is detrimental to the path of spiritual progress. One should become accustomed to this and reject anything which is against the path of spiritual progress. This is real renunciation. The senses are so strong that they are always anxious to have sense gratification. One should not cater to these demands, which are not necessary. The senses should only be gratified to keep the body fit so that one can discharge his duty in advancing in spiritual life. The most important and uncontrollable sense is the tongue. If one can control the tongue, then there is every possibility of controlling the other senses. The function of the tongue is to taste and to vibrate. Therefore, by systematic regulation, the tongue should always be engaged in tasting the remnants of foodstuffs offered to Kṛṣṇa and chanting Hare Kṛṣṇa. As far as the eyes are concerned, they should not be allowed to see anything but the beautiful form of Kṛṣṇa. That will control the eyes. Similarly, the ears should be engaged in hearing about Kṛṣṇa and the nose in smelling the flowers offered to Kṛṣṇa. This is the process of devotional service, and it is understood here that Bhagavad-gītā is simply expounding the science of devotional service. Devotional service is the main and sole objective. Unintelligent commentators on the Bhagavad-gītā try to divert the mind of the reader to other subjects, but there is no other subject in Bhagavad-gītā than devotional service."])self.__next_f.push([1,"66:[\"$\",\"$L2f\",\"child-3664\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:6\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$70\"}}]}]\n67:[\"$\",\"$L2f\",\"child-3665\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:7\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"False ego means accepting this body as oneself. When one understands that he is not his body and is spirit soul, he comes to his real ego. Ego is there. False ego is condemned, but not real ego. In the Vedic literature (Bṛhad-āraṇyaka Upaniṣad 1.4.10) it is said, ahaṁ brahmāsmi: I am Brahman, I am spirit. This “I am,” the sense of self, also exists in the liberated stage of self-realization. This sense of “I am” is ego, but when the sense of “I am” is applied to this false body it is false ego. When the sense of self is applied to reality, that is real ego. There are some philosophers who say we should give up our ego, but we cannot give up our ego, because ego means identity. We ought, of course, to give up the false identification with the body.\"}}]}]\n71:T418,One should try to understand the distress of accepting birth, death, old age and disease. There are descriptions in various Vedic literatures of birth. In the Śrīmad-Bhāgavatam the world of the unborn, the child’s stay in the womb of the mother, its suffering, etc., are all very graphically described. It should be thoroughly understood that birth is distressful. Because we forget how much distress we have suffered within the womb of the mother, we do not make any solution to the repetition of birth and death. Similarly at the time of death there are all kinds of sufferings, and they are also mentioned in the authoritative scriptures. These should be discussed. And as far as disease and old age are concerned, everyone gets practical experience. No one wants to be diseased, and no one wants to become old, but there is no avoiding these. Unless we have a pessimistic view of this material life, considering the distresses of birth, death, old age and disease, there is no impetus for our making advancement in spiritual life.68:[\"$\",\"$L2f\",\"child-3666\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:8\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$71\"}}]}]\n72:T71d,"])self.__next_f.push([1,"As for detachment from children, wife and home, it is not meant that one should have no feeling for these. They are natural objects of affection. But when they are not favorable to spiritual progress, then one should not be attached to them. The best process for making the home pleasant is Kṛṣṇa consciousness. If one is in full Kṛṣṇa consciousness, he can make his home very happy, because this process of Kṛṣṇa consciousness is very easy. One need only chant Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare, accept the remnants of foodstuffs offered to Kṛṣṇa, have some discussion on books like Bhagavad-gītā and Śrīmad-Bhāgavatam, and engage oneself in Deity worship. These four things will make one happy. One should train the members of his family in this way. The family members can sit down morning and evening and chant together Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare. If one can mold his family life in this way to develop Kṛṣṇa consciousness, following these four principles, then there is no need to change from family life to renounced life. But if it is not congenial, not favorable for spiritual advancement, then family life should be abandoned. One must sacrifice everything to realize or serve Kṛṣṇa, just as Arjuna did. Arjuna did not want to kill his family members, but when he understood that these family members were impediments to his Kṛṣṇa realization, he accepted the instruction of Kṛṣṇa and fought and killed them. In all cases, one should be detached from the happiness and distress of family life, because in this world one can never be fully happy or fully miserable."])self.__next_f.push([1,"69:[\"$\",\"$L2f\",\"child-3667\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:9\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$72\"}}]}]\n6a:[\"$\",\"$L2f\",\"child-3668\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:10\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Happiness and distress are concomitant factors of material life. One should learn to tolerate, as advised in Bhagavad-gītā. One can never restrict the coming and going of happiness and distress, so one should be detached from the materialistic way of life and be automatically equipoised in both cases. Generally, when we get something desirable we are very happy, and when we get something undesirable we are distressed. But if we are actually in the spiritual position these things will not agitate us. To reach that stage, we have to practice unbreakable devotional service. Devotional service to Kṛṣṇa without deviation means engaging oneself in the nine processes of devotional service – chanting, hearing, worshiping, offering respect, etc. – as described in the last verse of the Ninth Chapter. That process should be followed.\"}}]}]\n6b:[\"$\",\"$L2f\",\"child-3669\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:11\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Naturally, when one is adapted to the spiritual way of life, he will not want to mix with materialistic men. That would go against his grain. One may test himself by seeing how far he is inclined to live in a solitary place, without unwanted association. Naturally a devotee has no taste for unnecessary sporting or cinema-going or enjoying some social function, because he understands that these are simply a waste of time. There are many research scholars and philosophers who study sex life or some other subject, but according to Bhagavad-gītā such research work and philosophical speculation have no value. That is more or less nonsensical. According to Bhagavad-gītā, one should make research, by philosophical discretion, into the nature of the soul. One should make research to understand the self. That is recommended here.\"}}]}]\n6c:[\"$\",\"$L2f\",\"child-3670\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:12\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"As far as self-realization is concerned, it is clearly stated here that bhakti-yoga is especially practical. As soon as there is a question of devotion, one must consider the relationship between the Supersoul and the individual soul. The individual soul and the Supersoul cannot be one, at least not in the bhakti conception, the devotional conception of life. This service of the individual soul to the Supreme Soul is eternal, nityam, as it is clearly stated. So bhakti, or devotional service, is eternal. One should be established in that philosophical conviction.\"}}]}]\n6d:[\"$\",\"$L2f\",\"child-3671\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:13\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"In the \",[\"$\",\"$L20\",\"1\",{\"href\":\"/en/library/sb/1/2/11/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Śrīmad-Bhāgavatam\"}],\" (1.2.11)\"]}],\" this is explained. \",[\"$\",\"em\",\"3\",{\"children\":\"Vadanti tat tattva-vidas tattvaṁ yaj jñānam advayam.\"}],\" “Those who are actually knowers of the Absolute Truth know that the Self is realized in three different phases, as Brahman, Paramātmā and Bhagavān.” Bhagavān is the last word in the realization of the Absolute Truth; therefore one should reach up to that platform of understanding "])self.__next_f.push([1,"the Supreme Personality of Godhead and thus engage in the devotional service of the Lord. That is the perfection of knowledge.\"]}]}]\n73:T468,Beginning from practicing humility up to the point of realization of the Supreme Truth, the Absolute Personality of Godhead, this process is just like a staircase beginning from the ground floor and going up to the top floor. Now on this staircase there are so many people who have reached the first floor, the second or the third floor, etc., but unless one reaches the top floor, which is the understanding of Kṛṣṇa, he is at a lower stage of knowledge. If anyone wants to compete with God and at the same time make advancement in spiritual knowledge, he will be frustrated. It is clearly stated that without humility, understanding is not truly possible. To think oneself God is most puffed up. Although the living entity is always being kicked by the stringent laws of material nature, he still thinks, “I am God” because of ignorance. The beginning of knowledge, therefore, is amānitva, humility. One should be humble and know that he is subordinate to the Supreme Lord. Due to rebellion against the Supreme Lord, one becomes subordinate to material nature. One must know and be convinced of this truth.6e:[\"$\",\"$L2f\",\"child-3672\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:14\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$73\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a34059e0ddb3f501'',t:''MTc4ODIyNDU2Mw==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.body.appendChild(a);if(''loading''!==document.readyState)c();else if(window.addEventListener)document.addEventListener(''DOMContentLoaded'',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);''loading''!==document.readyState&&(document.onreadystatechange=e,c())}}}})();', 'https://vedabase.io/en/library/bg/13/8-12/', true)
